    env: env,
    platform: 'android',
    arch: 'arm64',
    title: 'node',
    pid: 1,
    version: 'v18.16.0',
    versions: { node: '18.16.0', pocketrun: '1.0' },
    execPath: '/usr/local/bin/node',
    stdout: new Writable('out'),
    stderr: new Writable('err'),
    exit: function (code) {
